using System.Collections;using UnityEngine;using UnityEngine.UI;
namespace Caronte {
public class StationPolish : MonoBehaviour {
 public CaronteStation station;public Transform planet;public Material particleMaterial,orbitMaterial;public float planetDegreesPerSecond=.35f,orbitSeconds=20,orbitRadius=95; public float VisualPhase{get{return phase;}}bool wasFlying;
 public Transform WindowCraft {get{return orbitalCraft;}} Transform orbitalCraft;LineRenderer orbit;float phase;int revision=-1;float refreshAfter;CanvasGroup screenGroup;bool priorConsole;
 public int DockBursts {get;private set;}
 void Start(){
 planet=transform.Find("DestinationEarth");var old=transform.Find("WindowSatelliteOrbit");if(old)Destroy(old.gameObject);
 }
 Vector3 Position(float a){return planet.position+new Vector3(Mathf.Cos(a)*orbitRadius,Mathf.Sin(a)*orbitRadius*.9421f,Mathf.Sin(a)*orbitRadius*.3347f);}
 void Update(){var room=GetComponent<StationRoomController>();if(room&&room.IsPaused)return;
 if(planet){bool flying=station.app.Stage>=3&&station.app.CurrentEngine!=null;var loss=GetComponent<OrbitalFailureController>();if(!flying){if(orbitalCraft)Destroy(orbitalCraft.gameObject);orbitalCraft=null;revision=-1;refreshAfter=0;}else if(!(loss&&loss.Destroyed)&&!orbitalCraft)RebuildOrbitCraft();planet.Rotate(Vector3.up,planetDegreesPerSecond*Time.deltaTime,Space.World);if(flying&&!wasFlying)phase=0;wasFlying=flying;if(flying)phase=Mathf.Repeat(phase+Time.deltaTime/Mathf.Max(1,orbitSeconds)*Mathf.PI*2,Mathf.PI*2);int rev=JsonUtility.ToJson(station.app.Configuration).GetHashCode();if(flying&&rev!=revision){revision=rev;refreshAfter=Time.time+1.2f;}if(flying&&!(loss&&loss.Destroyed)&&refreshAfter>0&&Time.time>=refreshAfter){refreshAfter=0;RebuildOrbitCraft();}
 if(orbitalCraft){orbitalCraft.position=Position(phase);orbitalCraft.rotation=Quaternion.LookRotation((Position(phase+.01f)-orbitalCraft.position).normalized,(orbitalCraft.position-planet.position).normalized);if(station.app.Stage>=3&&station.app.CurrentEngine!=null){var block=new MaterialPropertyBlock();foreach(var r in orbitalCraft.GetComponentsInChildren<Renderer>()){r.GetPropertyBlock(block);block.SetColor("_BaseColor",r.sharedMaterial.color*(station.app.CurrentEngine.Eclipse?.25f:1));r.SetPropertyBlock(block);}}}}
 var console=station.app.transform.Find("MissionConsole");if(console&&screenGroup==null){screenGroup=console.gameObject.AddComponent<CanvasGroup>();screenGroup.alpha=.85f;}
 if(screenGroup)screenGroup.alpha=Mathf.Lerp(screenGroup.alpha,station.ConsoleActive?1:.86f,1-Mathf.Exp(-Time.deltaTime*5));
 if(priorConsole!=station.ConsoleActive){priorConsole=station.ConsoleActive;PulseScreen();}
 }
 void RebuildOrbitCraft(){if(orbitalCraft)Destroy(orbitalCraft.gameObject);orbitalCraft=Instantiate(station.app.spacecraft.gameObject).transform;orbitalCraft.name="WindowOrbitCubeSat";orbitalCraft.SetParent(transform,false);orbitalCraft.gameObject.SetActive(true);orbitalCraft.localScale=Vector3.one*1.1f;foreach(var t in orbitalCraft.GetComponentsInChildren<Transform>(true))t.gameObject.layer=0;foreach(var t in orbitalCraft.GetComponentsInChildren<Transform>(true))if(t.name.EndsWith("Anchor"))foreach(Transform module in t){if(module.name.StartsWith("Payload_")||module.name.StartsWith("Solar_")||module.name.StartsWith("Battery_")||module.name.StartsWith("Radio_")||module.name.StartsWith("Storage_")){module.localPosition=Vector3.zero;module.localRotation=Quaternion.identity;}}}
 public void PulseScreen(){if(screenGroup)screenGroup.alpha=.55f;}
 public void DockEffect(Vector3 position,bool finish=false){DockBursts++;var go=new GameObject(finish?"AssemblyCompleteParticles":"AssemblyDockParticles");go.transform.SetParent(transform,false);go.transform.position=position;
 var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.loop=false;main.playOnAwake=false;main.startLifetime=new ParticleSystem.MinMaxCurve(.3f,finish?.8f:1.15f);main.startSpeed=new ParticleSystem.MinMaxCurve(finish?.08f:.6f,finish?1.1f:1.8f);main.startSize=new ParticleSystem.MinMaxCurve(.012f,.035f);main.gravityModifier=finish?.15f:2.8f;main.simulationSpace=ParticleSystemSimulationSpace.World;main.startColor=finish?new Color(.2f,1,.8f):new Color(1,.65f,.15f);
 var size=ps.sizeOverLifetime;size.enabled=true;size.size=new ParticleSystem.MinMaxCurve(1,AnimationCurve.EaseInOut(0,1,1,0));var collision=ps.collision;collision.enabled=!finish;collision.type=ParticleSystemCollisionType.World;collision.mode=ParticleSystemCollisionMode.Collision3D;collision.bounce=.22f;collision.dampen=.65f;collision.lifetimeLoss=.35f;collision.collidesWith=1;collision.quality=ParticleSystemCollisionQuality.Medium;var emission=ps.emission;emission.enabled=false;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Sphere;shape.radius=.035f;
 var renderer=go.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=particleMaterial;ps.Emit(finish?96:30);Destroy(go,1.2f);
 StartCoroutine(Flash(position,finish));}
 IEnumerator Flash(Vector3 p,bool finish){var g=new GameObject("DockConfirmationLight");g.transform.SetParent(transform,false);g.transform.position=p;var l=g.AddComponent<Light>();l.type=LightType.Point;l.range=finish?2.5f:.7f;l.color=new Color(.25f,.8f,1);for(float t=0;t<1;t+=Time.deltaTime/.35f){l.intensity=(1-t)*(finish?3:1);yield return null;}Destroy(g);}
 public static StationIcon Decorate(Transform panel,int kind,float x,float y,float size){var go=new GameObject("SubsystemIcon",typeof(RectTransform),typeof(CanvasRenderer),typeof(StationIcon));go.transform.SetParent(panel,false);var rt=go.GetComponent<RectTransform>();rt.anchorMin=rt.anchorMax=new Vector2(0,1);rt.pivot=new Vector2(0,1);rt.anchoredPosition=new Vector2(x,-y);rt.sizeDelta=Vector2.one*size;var icon=go.GetComponent<StationIcon>();icon.kind=kind;icon.color=new Color(.3f,.85f,1);icon.raycastTarget=false;return icon;}
}
}